INSERT INTO jobs (title, company, description, location) VALUES
('Senior Full-Stack Engineer', 'Northwind Labs', 'Own customer-facing features end to end in React, TypeScript, Node and Postgres. You will lead the checkout rewrite, mentor two mid-level engineers, and own your service''s SLOs. Remote, United States only, must overlap 9am-3pm US Eastern.', 'Remote (US, ET overlap)'),
('ML Platform Engineer', 'Lumen Health', 'Build and run the feature store and training pipelines for 40+ production models. Python, Kubernetes, Feast, Airflow, dbt. Berlin hybrid or EU remote. You care about feature freshness, reproducibility, and p95s.', 'Berlin hybrid / EU remote'),
('Founding Mobile Engineer', 'Tangerine Social', 'Be employee #5 and own the React Native app end to end, with native Swift modules where they matter. On-site in San Francisco. Consumer app with 2M DAU, ship daily.', 'San Francisco (on-site)'),
('Backend Engineer, Payments', 'Tidewater Bank', 'Own payment rails in Go. Postgres, Kafka, idempotency, reconciliation. You have opinions about exactly-once semantics. Hybrid in Toronto, open to relocation for the right person.', 'Toronto (hybrid)'),
('Frontend Engineer, Design Systems', 'Orbit Analytics', 'Own the charting and design system used by every product team. React, TypeScript, canvas performance, accessibility. Hybrid in Berlin.', 'Berlin (hybrid)'),
('Data Engineer', 'Lumen Health', 'Own the claims data pipeline end to end: Spark, Airflow, dbt, Snowflake, data contracts. Remote EU-friendly hours.', 'Remote (EU hours)');

